import type { FreeCamera } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };
export interface ChaseCamera { camera: FreeCamera; bank(up: Vec): void }

const EPS = 1e-12;

function normalizeTo(out: Vec, v: Vec): boolean { ... }
function writeUp(camera: FreeCamera, up: Vec): void {
  const uv = (camera as unknown as { upVector?: Vec }).upVector;
  if (!uv) return;
  uv.x = up.x; uv.y = up.y; uv.z = up.z;
}

export function createChaseCamera(eye: Vec, target: Vec): ChaseCamera {
  const camera = createBankedFreeCamera(
    { x: eye.x, y: eye.y, z: eye.z },
    { x: target.x, y: target.y, z: target.z },
    { x: 0, y: 1, z: 0 }
  );

  const getForward = (out: Vec): boolean => {
    const pos = (camera as unknown as { position?: Vec }).position;
    const tgt = (camera as unknown as { target?: Vec }).target;
    if (!pos || !tgt) return false;
    out.x = tgt.x - pos.x; out.y = tgt.y - pos.y; out.z = tgt.z - pos.z;
    return normalizeTo(out, out);
  };

  // If the initial world-up reference is parallel to the line of sight, choose a horizontal reference so the camera can still look at the target.
  const f = { x: 0, y: 0, z: 0 };
  if (getForward(f)) {
    const worldUp = { x: 0, y: 1, z: 0 };
    const dot = f.x * worldUp.x + f.y * worldUp.y + f.z * worldUp.z;
    if (Math.abs(dot) > 1 - EPS) {
      const up = { x: 0, y: 0, z: 0 };
      const ax = Math.abs(f.x), ay = Math.abs(f.y), az = Math.abs(f.z);
      if (ax <= ay && ax <= az) { up.x = 1; up.y = 0; up.z = 0; }
      else if (ay <= ax && ay <= az) { up.x = 0; up.y = 1; up.z = 0; }
      else { up.x = 0; up.y = 0; up.z = 1; }
      const d = up.x * f.x + up.y * f.y + up.z * f.z;
      up.x -= f.x * d; up.y -= f.y * d; up.z -= f.z * d;
      normalizeTo(up, up);
      writeUp(camera, up);
    }
  }

  const bank = (up: Vec): void => {
    const f = { x: 0, y: 0, z: 0 };
    if (!getForward(f)) return;
    const u = { x: up.x, y: up.y, z: up.z };
    if (!normalizeTo(u, u)) return;
    const dot = f.x * u.x + f.y * u.y + f.z * u.z;
    if (Math.abs(dot) > 1 - EPS) return;
    writeUp(camera, u);
  };

  return { camera, bank };
}
